import{_ as o,l,o as e,c as s,v as t,p as n,x as r,d as c,i as d,S as T}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"WebRTC 与 ICE","description":"","frontmatter":{"title":"WebRTC 与 ICE","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/webrtc-ice.md","filePath":"cs/webrtc-ice.md","lastUpdated":1789023840000}'),p={name:"cs/webrtc-ice.md"};function C(h,a,E,P,_,b){const i=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="webrtc-与-ice" tabindex="-1">WebRTC 与 ICE <a class="header-anchor" href="#webrtc-与-ice" aria-label="Permalink to &quot;WebRTC 与 ICE&quot;">​</a></h1><div class="epigraph"><p>浏览器直连音视频与数据：ICE 收集候选、连通性检查，选出能打通 NAT 的路径；媒体走 SRTP，信令另给。</p><footer>—— 据 RFC 8445 ICE；RFC 8825 WebRTC 概览整理</footer></div><p><a href="/cs/bittorrent-dht">BT</a> 要发现对等。<a href="/cs/dhcp-nat">NAT</a> 挡直连。<a href="/cs/bittorrent-dht">上一课</a> 不解决实时媒体。缺口是 <strong>WebRTC + ICE</strong>：候选、检查、与下一课 STUN/TURN 分工。本课不把 STUN 消息写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>通话要低延迟，不宜都走服务器中继（除非必要）。WebRTC：浏览器 API，ICE 把 host/srflx/relay 候选配对打连通性检查（STUN 绑定），同意一条。信令（SDP offer/answer）经你的 HTTPS 服务器，不规定死。媒体 DTLS-SRTP。与 QUIC 对照：都可 NAT 上的 UDP；ICE 更早。</p><p>不要把 ICE 写成 SDN 控制器。</p><p><span class="marginnote">RFC 8445。Trickle ICE 增量候选。本课钉对象。</span></p><h3 id="信令与媒体分离" tabindex="-1">信令与媒体分离 <a class="header-anchor" href="#信令与媒体分离" aria-label="Permalink to &quot;信令与媒体分离&quot;">​</a></h3><p>ICE 选能通的候选。尽量 P2P，失败才中继。没有信令通道则不能开始。对称 NAT 常要 TURN。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画：收集候选 → 检查 → 选定。对照 SSH 转发：那是叠 TCP；ICE 尽量直连 UDP。与 MPTCP：多候选类似多径，选出后通常一条媒体路。</p>',11)),(e(),n(T,null,{default:r(()=>[d(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20SIG%5B%22%E4%BF%A1%E4%BB%A4%20SDP%22%5D%20--%3E%20ICE%5B%22%E6%94%B6%E9%9B%86%E5%80%99%E9%80%89%22%5D%0A%20%20ICE%20--%3E%20CHK%5B%22%E8%BF%9E%E9%80%9A%E6%80%A7%E6%A3%80%E6%9F%A5%22%5D%0A%20%20CHK%20--%3E%20P2P%5B%22%E7%9B%B4%E8%BF%9E%E6%88%96%E4%B8%AD%E7%BB%A7%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>对称 NAT 失败则 TURN。企业防火墙禁 UDP 则全中继，延迟像卫星。拥塞：GCC/NACK 在媒体，不是 Reno 名。PTP 不需要。Cookie 会话在信令侧。</p><p>安全：DTLS 身份，防注入。不写扫描。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 simulcast 的全部。STUN/TURN 是下一课。后课默认：ICE 选路；媒体尽量 P2P。</p><p>没有信令通道，ICE 不能开始。</p><p>上一课留下的缺口在本课收口；「WebRTC 与 ICE」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/stun-turn">STUN / TURN</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>ICE 用候选与检查穿过 NAT。</li><li>信令与媒体分离。</li><li>失败才中继，延迟上升。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 8445；RFC 8825。</li></ul>',10))])}const I=o(p,[["render",C]]);export{u as __pageData,I as default};
